export function importSetScript(source, map, log, target) {
    // ImportSet script validation with module support
    log.info('Running ImportSet script validation with module')

    // Validate required fields
    if (!source.getValue('name')) {
        log.error('Name field is required')
        return false
    }

    if (!source.getValue('email')) {
        log.error('Email field is required')
        return false
    }

    // Log successful validation
    const name = source.getValue('name')
    log.info(`Validation passed for: ${name}`)
    return true
}
